import{_ as e,o as r,c as t,b3 as h}from"./chunks/framework.VnelH-cX.js";const p=JSON.parse('{"title":"系统设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings/system.md","filePath":"guide/settings/system.md","lastUpdated":1786700458000}'),o={name:"guide/settings/system.md"};function i(l,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="系统设置" tabindex="-1">系统设置 <a class="header-anchor" href="#系统设置" aria-label="Permalink to &quot;系统设置&quot;">​</a></h1><p>系统设置页面包含了应用的核心配置选项，帮助你自定义 Wing Shot 的运行方式和行为</p><h2 id="常用" tabindex="-1">常用 <a class="header-anchor" href="#常用" aria-label="Permalink to &quot;常用&quot;">​</a></h2><h3 id="开机自动启动" tabindex="-1">开机自动启动 <a class="header-anchor" href="#开机自动启动" aria-label="Permalink to &quot;开机自动启动&quot;">​</a></h3><p>Wing Shot 会在系统启动时自动运行，无需手动启动应用</p><h3 id="自动检查更新" tabindex="-1">自动检查更新 <a class="header-anchor" href="#自动检查更新" aria-label="Permalink to &quot;自动检查更新&quot;">​</a></h3><p>应用会定期检查新版本，存在更新时则提示用户</p><h3 id="运行日志" tabindex="-1">运行日志 <a class="header-anchor" href="#运行日志" aria-label="Permalink to &quot;运行日志&quot;">​</a></h3><p>Wing Shot 将记录应用功能异常时的运行信息，用于问题反馈和修复</p><h3 id="管理员权限" tabindex="-1">管理员权限 <a class="header-anchor" href="#管理员权限" aria-label="Permalink to &quot;管理员权限&quot;">​</a></h3><p>使用管理员权限截图此应用，开启后可以在更多窗口中通过快捷键唤起应用功能</p><h2 id="截图" tabindex="-1">截图 <a class="header-anchor" href="#截图" aria-label="Permalink to &quot;截图&quot;">​</a></h2><h3 id="启用多显示器截图" tabindex="-1">启用多显示器截图 <a class="header-anchor" href="#启用多显示器截图" aria-label="Permalink to &quot;启用多显示器截图&quot;">​</a></h3><p>开启后，可以跨多个显示器进行截图操作</p><h3 id="更正颜色滤镜" tabindex="-1">更正颜色滤镜 <a class="header-anchor" href="#更正颜色滤镜" aria-label="Permalink to &quot;更正颜色滤镜&quot;">​</a></h3><p>还原系统应用颜色滤镜（如反色等）后的截图内容</p><h3 id="更正-hdr-颜色" tabindex="-1">更正 HDR 颜色 <a class="header-anchor" href="#更正-hdr-颜色" aria-label="Permalink to &quot;更正 HDR 颜色&quot;">​</a></h3><p>对 HDR 显示器的截图进行颜色校正。可以选择不同的 HDR 颜色转换算法（如线性转换）来获得最佳效果</p><h3 id="记录截图历史" tabindex="-1">记录截图历史 <a class="header-anchor" href="#记录截图历史" aria-label="Permalink to &quot;记录截图历史&quot;">​</a></h3><p>每次完成截图操作后，将截图信息保存供后续返回修改</p><h3 id="截图历史有效时长" tabindex="-1">截图历史有效时长 <a class="header-anchor" href="#截图历史有效时长" aria-label="Permalink to &quot;截图历史有效时长&quot;">​</a></h3><p>截图历史保存的有效时间，截图记录过期后会自动删除对应的记录数据，节省硬盘空间。</p><h3 id="截图历史保存编辑结果" tabindex="-1">截图历史保存编辑结果 <a class="header-anchor" href="#截图历史保存编辑结果" aria-label="Permalink to &quot;截图历史保存编辑结果&quot;">​</a></h3><p>记录截图历史时也保留截图的编辑结果</p><h3 id="文本识别热启动" tabindex="-1">文本识别热启动 <a class="header-anchor" href="#文本识别热启动" aria-label="Permalink to &quot;文本识别热启动&quot;">​</a></h3><p>提前加载文本识别模型，提高文本识别速度</p><h3 id="文本识别模型写入内存" tabindex="-1">文本识别模型写入内存 <a class="header-anchor" href="#文本识别模型写入内存" aria-label="Permalink to &quot;文本识别模型写入内存&quot;">​</a></h3><p>将文本识别模型写入内存，减少硬盘数据的读写</p><h3 id="文本识别检测角度" tabindex="-1">文本识别检测角度 <a class="header-anchor" href="#文本识别检测角度" aria-label="Permalink to &quot;文本识别检测角度&quot;">​</a></h3><p>尝试纠正文本倒置的情况</p><h3 id="尝试降低复制的图片大小" tabindex="-1">尝试降低复制的图片大小 <a class="header-anchor" href="#尝试降低复制的图片大小" aria-label="Permalink to &quot;尝试降低复制的图片大小&quot;">​</a></h3><p>复制图片时尝试丢弃图像的 Alpha 通道，以便在部分软件保存复制图像时获得更小的文件占用</p><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="系统代理" tabindex="-1">系统代理 <a class="header-anchor" href="#系统代理" aria-label="Permalink to &quot;系统代理&quot;">​</a></h3><p>应用将使用系统配置的代理设置进行网络连接</p><h2 id="滚动截图" tabindex="-1">滚动截图 <a class="header-anchor" href="#滚动截图" aria-label="Permalink to &quot;滚动截图&quot;">​</a></h2><p>滚动截图功能可以捕获需要滚动查看的长页面内容</p><h3 id="匹配两侧图片" tabindex="-1">匹配两侧图片 <a class="header-anchor" href="#匹配两侧图片" aria-label="Permalink to &quot;匹配两侧图片&quot;">​</a></h3><p>滚动截图存在上下、左右两种情况，滚动时会根据滚动方向匹配一侧图片，开启后会在一侧匹配失败时尝试匹配另一侧里（常适用于匹配失败重新滚动到匹配失败位置时，如果关闭，必须再次向匹配方向进行滚动操作，但可能存在错误匹配导致拼接错误的情况动截图</p><h3 id="图片特征阈值" tabindex="-1">图片特征阈值 <a class="header-anchor" href="#图片特征阈值" aria-label="Permalink to &quot;图片特征阈值&quot;">​</a></h3><p>值越低，匹配的特征点越多</p><h3 id="采样率" tabindex="-1">采样率 <a class="header-anchor" href="#采样率" aria-label="Permalink to &quot;采样率&quot;">​</a></h3><p>数值越大拼接越精确</p><h3 id="采样最小边长" tabindex="-1">采样最小边长 <a class="header-anchor" href="#采样最小边长" aria-label="Permalink to &quot;采样最小边长&quot;">​</a></h3><p>数值越大，拼接越精确</p><h3 id="采样最大大小" tabindex="-1">采样最大大小 <a class="header-anchor" href="#采样最大大小" aria-label="Permalink to &quot;采样最大大小&quot;">​</a></h3><p>数值越大，拼接越精确</p><h3 id="图片特征描述大小" tabindex="-1">图片特征描述大小 <a class="header-anchor" href="#图片特征描述大小" aria-label="Permalink to &quot;图片特征描述大小&quot;">​</a></h3><p>合适的数值能有更好的拼接识别效果</p><h2 id="ai-对话" tabindex="-1">AI 对话 <a class="header-anchor" href="#ai-对话" aria-label="Permalink to &quot;AI 对话&quot;">​</a></h2><p>配置 AI 对话功能的参数，影响 AI 的响应质量和速度</p><h3 id="最大-token-数" tabindex="-1">最大 Token 数 <a class="header-anchor" href="#最大-token-数" aria-label="Permalink to &quot;最大 Token 数&quot;">​</a></h3><p>设置单次对话的最大 Token 数量</p><h3 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h3><p>控制 AI 回复的创造性程度，范围 0-2：</p><ul><li>接近 0：回复更加确定和一致</li><li>接近 2：回复更加多样和创造性</li></ul><h3 id="思考预算-token-数" tabindex="-1">思考预算 Token 数 <a class="header-anchor" href="#思考预算-token-数" aria-label="Permalink to &quot;思考预算 Token 数&quot;">​</a></h3><p>设置 AI 进行深度思考时可用的 Token 预算</p><h2 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h2><h3 id="热加载页面数量" tabindex="-1">热加载页面数量 <a class="header-anchor" href="#热加载页面数量" aria-label="Permalink to &quot;热加载页面数量&quot;">​</a></h3><p>提高固定到屏幕、视频录制等功能的响应速度，但也提高了内存的占用</p><h2 id="软件数据" tabindex="-1">软件数据 <a class="header-anchor" href="#软件数据" aria-label="Permalink to &quot;软件数据&quot;">​</a></h2><p>管理应用的数据存储位置和清理选项</p><h3 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h3><p>存放配置、截图历史等数据的根目录</p><h3 id="配置目录" tabindex="-1">配置目录 <a class="header-anchor" href="#配置目录" aria-label="Permalink to &quot;配置目录&quot;">​</a></h3><p>软件配置的存放目录</p><h3 id="日志目录" tabindex="-1">日志目录 <a class="header-anchor" href="#日志目录" aria-label="Permalink to &quot;日志目录&quot;">​</a></h3><p>运行日志的输入目录，开启<code>运行日志</code>后生效。</p><h3 id="清除所有数据" tabindex="-1">清除所有数据 <a class="header-anchor" href="#清除所有数据" aria-label="Permalink to &quot;清除所有数据&quot;">​</a></h3><p>点击&quot;清除所有数据&quot;按钮将删除所有截图、历史记录、配置等数据。此操作不可恢复，请谨慎使用。</p>',71)])])}const q=e(o,[["render",i]]);export{p as __pageData,q as default};
